# ==== shard prelude (generated by scripts/build_corpus_kernels.py) ====
# A Kaggle script kernel gets no argv, so the shard parameters ride in the environment.
import os as _os
_os.environ.setdefault('CORPUS_MODE', 'build64')
_os.environ.setdefault('CORPUS_START', '1653')
_os.environ.setdefault('CORPUS_COUNT', '551')
_os.environ.setdefault('CORPUS_SHARD', 's3')
_os.environ.setdefault('CORPUS_THREADS', '4')
# ==== end shard prelude ====
# -*- coding: utf-8 -*-
"""Build the 64-slot DENSE corpus -- the frontier's own recipe -- from the competition DICOM.
CPU only: no GPU, no TPU quota.

THE RECIPE (all read out of the frontier's inference notebook, nothing guessed)
    64 slots/study = [("Sagittal",1,18), ("Sagittal",0,14), ("Coronal",1,12), ("Coronal",0,8), ("Axial",-1,12)]
    span (0.02, 0.98) of the position-ordered series
    indices = np.rint(np.linspace(lo*(n-1), hi*(n-1), k))          (FACTS C72: linspace, rounded)
    140 mm centre crop then resize                                  (C58/C72: correlation ~0.99)
    missing (plane,fluid) -> the whole group is ZEROS with mask 0    (C74-C76: confirmed on the
                                                                     published corpus, 25.8% of
                                                                     studies have no Coronal fluid=0)

WHY THIS FILE IS THE SECOND VERSION -- the first one measured 8 studies in >40 min, i.e. ~5 min per
study, which extrapolates to ~367 h single-threaded for the full set.  Three fixes -- and MEASURED
at 0.7 s/study afterwards (`shard s0: (551, 64, 336, 336) | 391s`), about 150x faster than the old
per-study figure.  That number is why the whole corpus is a ten-minute job and not a two-day one:

  1. ONE series scan per group, not per candidate.  The first version read every candidate series'
     full header stack just to choose the LONGEST one.  Now the winner is picked by counting .dcm
     files (a directory listing) and only that series is scanned.
  2. `specific_tags=` on every header read.  Ordering needs exactly three tags
     (ImagePositionPatient / ImageOrientationPatient / InstanceNumber); parsing the rest of the
     header is pure waste.  Header reads dominate: ~150-750 per study to order ~5 series.
  3. multiprocessing over studies (--threads), because the kernel has 4 vCPU and the first version
     used one.

⚠️ ROW ORDER IS A CONTRACT, and the pool is TWO datasets (see the pool block in main()):
`knee-raptor-corpus` (3200 studies) + `knee-raptor-corpus-ext` (1207) = the 4407-study train set,
concatenated in exactly the order the trainer's _open_ids() uses.  BOTH must be in dataset_sources.

And it deliberately keeps `--mode verify44`: rebuilding the ALREADY-PUBLISHED 44-slot corpus and
correlating slice by slice is the only way to prove the builder before spending hours on a new one.

    python build_corpus.py --mode verify44 --limit 8
    python build_corpus.py --mode build64 --start 0 --count 1100 --shard s0 --threads 4
"""
import argparse
import glob
import json
import os
import time
from multiprocessing import Pool

import numpy as np
import pandas as pd
import pydicom

GROUPS44 = [("Sagittal", 1, 12), ("Sagittal", 0, 10), ("Coronal", 1, 8),
            ("Coronal", 0, 6), ("Axial", -1, 8)]
GROUPS64 = [("Sagittal", 1, 18), ("Sagittal", 0, 14), ("Coronal", 1, 12),
            ("Coronal", 0, 8), ("Axial", -1, 12)]
# Span of the PUBLISHED corpus, FITTED from 35 trustworthy probe groups (`.testtmp/fit_rule.py`):
# FLOOR the two endpoints, then linspace between those integers -- reproduces 34/35 groups exactly
# with (0.152, 0.847).  The first builder used float endpoints + rint and reproduced 0/35.
# Every earlier "span is 2/3, centred at 0.485" reading (FACTS C72) was an artefact of that wrong
# rounding: with integer endpoints the centre is exactly 0.5 and the span is 70%.
SPAN44 = (0.152, 0.847)
SPAN64 = (0.02, 0.98)                # the frontier's maxspan recipe (their notebook, not fitted)

ORDER_TAGS = ["ImagePositionPatient", "ImageOrientationPatient", "InstanceNumber"]
CROP_MM = 140.0
OUT = 336
WORK = "/kaggle/working"

_TS = None
_ROOT = None
_GROUPS = None
_SPAN = None


def find(name):
    """Locate an input file WITHOUT walking the whole /kaggle/input tree.

    The first version used a single `glob('/kaggle/input/**/' + name, recursive=True)`, which
    traverses the entire competition mount -- 570 GB of DICOM in tens of thousands of directories.
    MEASURED on the rented-box verify run: the first stdout line appeared at **t = 1613 s**, i.e.
    ~27 minutes of pure directory walking before any work happened.  Known locations first, then
    shallow globs, and only fall back to the recursive walk if all else fails.
    """
    direct = [
        "/kaggle/input/competitions/rsna-knee-abnormality-detection/" + name,
        "/kaggle/input/rsna-knee-abnormality-detection/" + name,
    ]
    for p in direct:
        if os.path.exists(p):
            return p
    for pat in ("/kaggle/input/datasets/*/*/" + name,     # datasets mount at datasets/<owner>/<slug>/
                "/kaggle/input/*/" + name,
                "/kaggle/input/*/*/" + name):
        hits = sorted(glob.glob(pat))
        if hits:
            return hits[0]
    # Depth-bounded last resort.  This used to be a single `**` recursive glob, which is the exact
    # thing this function exists to avoid: MEASURED 2026-09-24, when `extra_ids.npy` was not mounted
    # the unbounded walk burned **623 s** before returning None -- ten minutes of pure directory
    # walking, longer than an entire successful shard build (391 s).  Never walk unbounded; try a
    # few explicit depths and then say what is actually mounted.
    for depth in (3, 4):
        hits = sorted(glob.glob("/kaggle/input/" + "*/" * depth + name))
        if hits:
            return hits[0]
    print("!! find(%r) FAILED -- not at any known mount. Mounted top level:" % name, flush=True)
    for d in sorted(glob.glob("/kaggle/input/*")):
        print("     %s" % d, flush=True)
    for d in sorted(glob.glob("/kaggle/input/datasets/*/*")):
        print("     %s" % d, flush=True)
    return None


def series_key(ds):
    iop = np.asarray(ds.ImageOrientationPatient, dtype=float)
    ipp = np.asarray(ds.ImagePositionPatient, dtype=float)
    return float(np.dot(ipp, np.cross(iop[:3], iop[3:])))


def scan(d):
    """Order ONE series along its slice normal.  Three tags only -- see the header note."""
    out = []
    for f in os.listdir(d):
        if not f.endswith(".dcm"):
            continue
        p = os.path.join(d, f)
        try:
            ds = pydicom.dcmread(p, stop_before_pixels=True, specific_tags=ORDER_TAGS)
            out.append((series_key(ds), p))
        except Exception:
            continue
    out.sort(key=lambda t: t[0])
    return out


def n_files(d):
    try:
        return sum(1 for f in os.listdir(d) if f.endswith(".dcm"))
    except Exception:
        return 0


def prep(path):
    ds = pydicom.dcmread(path)
    a = ds.pixel_array.astype(np.float32)
    a = a * float(getattr(ds, "RescaleSlope", 1) or 1) + float(getattr(ds, "RescaleIntercept", 0) or 0)
    ps = getattr(ds, "PixelSpacing", None)
    px = float(ps[0]) if ps is not None else None
    if px and px > 0:
        want = int(round(CROP_MM / px))
        h, w = a.shape
        if 16 < want < min(h, w):
            cy, cx = h // 2, w // 2
            half = want // 2
            a = a[cy - half:cy - half + want, cx - half:cx - half + want]
    lo, hi = float(a.min()), float(a.max())
    if hi > lo:
        a = (a - lo) / (hi - lo)
    try:
        import cv2
        a = cv2.resize(a, (OUT, OUT), interpolation=cv2.INTER_AREA)
    except Exception:
        ix = np.linspace(0, a.shape[0] - 1, OUT).astype(int)
        iy = np.linspace(0, a.shape[1] - 1, OUT).astype(int)
        a = a[np.ix_(ix, iy)]
    return np.clip(a * 255.0, 0, 255).astype(np.uint8)


def pick_indices(n, k, span):
    """The published corpus's rule, fitted (see SPAN44 note): FLOOR both endpoints to slice
    indices, then linspace between those INTEGERS and round.  Float endpoints then rounding
    reproduces none of the 35 measured groups; this form reproduces 34."""
    if n <= 1:
        return np.zeros(k, dtype=int)
    lo = int(np.floor(span[0] * (n - 1)))
    hi = int(np.floor(span[1] * (n - 1)))
    hi = max(hi, lo)
    return np.rint(np.linspace(lo, hi, k)).astype(int)


def build_study(uid):
    sub = _TS[_TS.StudyInstanceUID == uid]
    n_slot = sum(g[2] for g in _GROUPS)
    vols = np.zeros((n_slot, OUT, OUT), np.uint8)
    mask = np.zeros(n_slot, np.uint8)
    audit = []
    off = 0
    for plane, fluid, k in _GROUPS:
        got = sub[sub.Anatomical_Plane == plane]
        if fluid != -1:
            got = got[got.Fluid_Sensitive == fluid]
        # Pick the LONGEST candidate by counting files -- a directory listing, not 150 header reads.
        best_dir, best_n = None, 0
        for _, row in got.iterrows():
            d = os.path.join(_ROOT, uid, str(row.SeriesInstanceUID))
            c = n_files(d)
            if c > best_n:
                best_dir, best_n = d, c
        if best_dir is None:
            audit.append((plane, fluid, k, 0, []))
            off += k
            continue
        rows = scan(best_dir)
        if not rows:
            audit.append((plane, fluid, k, 0, []))
            off += k
            continue
        idx = pick_indices(len(rows), k, _SPAN)
        for j, i in enumerate(idx):
            try:
                vols[off + j] = prep(rows[int(i)][1])
                mask[off + j] = 1
            except Exception:
                pass
        audit.append((plane, fluid, k, len(rows), idx.tolist()))
        off += k
    return uid, vols, mask, audit


def _init(ts, root, groups, span):
    global _TS, _ROOT, _GROUPS, _SPAN
    _TS, _ROOT, _GROUPS, _SPAN = ts, root, groups, span


def corr_rows(a, b):
    A = a.reshape(a.shape[0], -1).astype(np.float32)
    B = b.reshape(b.shape[0], -1).astype(np.float32)
    A -= A.mean(1, keepdims=True); B -= B.mean(1, keepdims=True)
    A /= np.maximum(np.linalg.norm(A, axis=1, keepdims=True), 1e-6)
    B /= np.maximum(np.linalg.norm(B, axis=1, keepdims=True), 1e-6)
    return (A * B).sum(1)


def main():
    ap = argparse.ArgumentParser()
    # Defaults come from the ENVIRONMENT as well as argv, because a Kaggle *script* kernel receives
    # no command line: this is how one identical script file is fanned out into four concurrent
    # shard kernels without forking the code (the same prelude trick the training kernels use).
    ap.add_argument("--mode", choices=["verify44", "build64"],
                    default=os.environ.get("CORPUS_MODE", "verify44"))
    ap.add_argument("--limit", type=int, default=int(os.environ.get("CORPUS_LIMIT", 8)))
    ap.add_argument("--start", type=int, default=int(os.environ.get("CORPUS_START", 0)))
    ap.add_argument("--count", type=int, default=int(os.environ.get("CORPUS_COUNT", 1100)))
    ap.add_argument("--shard", default=os.environ.get("CORPUS_SHARD", "s0"))
    ap.add_argument("--threads", type=int, default=int(os.environ.get("CORPUS_THREADS", 4)))
    a = ap.parse_args()

    t0 = time.time()
    ts = pd.read_csv(find("train_series.csv"))
    root = os.path.join(os.path.dirname(find("train_series.csv")), "train_series")
    if not os.path.isdir(root):
        c = glob.glob("/kaggle/input/**/train_series", recursive=True)
        root = c[0] if c else root
    groups = GROUPS44 if a.mode == "verify44" else GROUPS64
    span = SPAN44 if a.mode == "verify44" else SPAN64
    print("train_series %d rows | root %s | mode %s | %d slots | threads %d" % (
        len(ts), root, a.mode, sum(g[2] for g in groups), a.threads), flush=True)

    # ---------------------------------------------------------------------------------------
    # ROW ORDER IS A CONTRACT.  The published corpus is TWO parts -- knee-raptor-corpus (3200
    # studies) and knee-raptor-corpus-ext (1207) -- and together they are exactly the 4407-study
    # training set.  The trainer's _open_ids() is `concat(all_ids, extra_ids)`, and every array
    # (vols / masks / ids / labels) is indexed by that one order.
    #
    # The first version of this builder read ONLY all_ids.npy, so `pool_list` was 3200 long: shard
    # s5 would have come up 106 rows short, and s6/s7 -- which cover rows 3306..4406, i.e. the
    # whole ext part -- would have produced EMPTY arrays.  Because the trainer takes the local
    # /kaggle/working/all_vols.npy in preference to both mounted parts, that would have handed
    # training a 4407-row id list against a truncated volume array: either an IndexError or a
    # 32-hour build discovered to be unusable.  Build all 4407 rows in the trainer's order.
    # ---------------------------------------------------------------------------------------
    def need(name):
        """find() plus a readable failure.  `np.load(None)` raises a bare
        `TypeError: expected str, bytes or os.PathLike object, not NoneType`, which says nothing
        about the actual problem -- on 2026-09-24 s5/s6/s7 died that way and the real cause was a
        dataset that was simply not in this kernel's dataset_sources."""
        p = find(name)
        if p is None:
            raise SystemExit(
                "input %r is not mounted in this kernel. The corpus is TWO datasets -- add "
                "'dreaddevelopment/knee-raptor-corpus' AND 'dreaddevelopment/knee-raptor-corpus-ext' "
                "to dataset_sources." % name)
        return p

    ids = np.array([str(x) for x in np.load(need("all_ids.npy"))])
    ext_ids = np.load(need("extra_ids.npy"), allow_pickle=True).astype(str)
    ids_all = np.concatenate([ids, ext_ids])
    in_ts = set(ts.StudyInstanceUID.astype(str))
    dropped = [u for u in ids_all if u not in in_ts]
    pool_list = [u for u in ids_all if u in in_ts]
    print("pool: corpus %d + ext %d = %d ids | dropped(absent from train_series) %d" % (
        len(ids), len(ext_ids), len(pool_list), len(dropped)), flush=True)
    if dropped:
        # A drop would shift EVERY subsequent row index, silently pairing studies with the wrong
        # volumes.  Measured 2026-09-24: all 4407 corpus ids are in train.csv, so this is 0.
        print("  WARNING %d dropped -> row indices SHIFT; do not use this shard" % len(dropped),
              flush=True)

    if a.mode == "verify44":
        ref = np.load(find("all_vols.npy"), mmap_mode="r")
        rng = np.random.default_rng(0)
        # Sample from part 1 only: the reference array covers just those 3200 rows.
        sample = list(rng.choice(ids, size=min(a.limit, len(ids)), replace=False))
        # Write a RESULT FILE as well as printing.  Learned the hard way: `kaggle kernels logs`
        # only ever returns the LATEST run's log, so once a second version is pushed the first
        # version's output becomes unreachable (FACTS A54).  A file in /kaggle/working survives
        # that, because `kaggle kernels output` fetches whatever the version produced.
        results = []
        with Pool(a.threads, initializer=_init, initargs=(ts, root, groups, span)) as p:
            for uid, v, m, audit in p.imap_unordered(build_study, sample):
                row = int(np.where(ids == uid)[0][0])
                if m.sum() == 0:
                    print("  row %-5d NO SERIES" % row, flush=True)
                    results.append({"row": row, "slots": 0, "verdict": "no-series"})
                    continue
                r = np.asarray(ref[row])[:v.shape[0]].astype(np.uint8)
                # Compare only slots where BOTH sides have real pixels.  The reference leaves a
                # group empty (mask 0, all-zero pixels) for 25.8% of studies; mean-centring an
                # all-zero vector divides by ~1e-6 and yields noise, which would read as a builder
                # mismatch when it is really a labelling disagreement (FACTS C74).
                keep = (m == 1) & (r.reshape(r.shape[0], -1).max(1) > 0)
                if keep.sum() == 0:
                    print("  row %-5d no overlapping real slots" % row, flush=True)
                    results.append({"row": row, "slots": int(m.sum()), "comparable": 0,
                                    "verdict": "no-overlap"})
                    continue
                c = corr_rows(v[keep], r[keep])
                verdict = "OK" if np.median(c) > 0.9 else "MISMATCH"
                print("  row %-5d slots %2d/%2d (comparable %2d)  corr min/med/max = %.3f / %.3f / %.3f  [%.0fs]" % (
                    row, int(m.sum()), v.shape[0], int(keep.sum()), c.min(), np.median(c), c.max(),
                    time.time() - t0), flush=True)
                for plane, fluid, k, n, idx in audit:
                    print("      %-9s fluid=%-3d k=%2d stack=%-4d idx=%s" % (
                        plane, fluid, k, n, idx[:6]), flush=True)
                print("      VERIFY %s" % verdict, flush=True)
                results.append({"row": row, "slots": int(m.sum()), "comparable": int(keep.sum()),
                                "corr_min": float(c.min()), "corr_med": float(np.median(c)),
                                "corr_max": float(c.max()), "verdict": verdict,
                                "audit": [{"plane": pl, "fluid": fl, "k": kk, "stack": nn,
                                           "idx": ix} for pl, fl, kk, nn, ix in audit]})
        meds = [r["corr_med"] for r in results if "corr_med" in r]
        summary = {
            "mode": "verify44", "reference": "dreaddevelopment/knee-raptor-corpus",
            "recipe": {"slots": sum(g[2] for g in groups), "span": list(span), "out": OUT,
                       "crop_mm": CROP_MM},
            "n_studies": len(results),
            "median_of_medians": float(np.median(meds)) if meds else None,
            "verdict": ("FAITHFUL" if meds and np.median(meds) > 0.9 else "MISMATCH"),
            "seconds": round(time.time() - t0, 1),
            "results": results,
        }
        with open(os.path.join(WORK, "verify_result.json"), "w") as f:
            json.dump(summary, f, indent=1)
        print("\n=== SUMMARY %s | median-of-medians %.4f | %.0fs ===" % (
            summary["verdict"], summary["median_of_medians"] or -1, time.time() - t0), flush=True)
        print("wrote /kaggle/working/verify_result.json", flush=True)
        print("DONE in %.0fs" % (time.time() - t0), flush=True)
        return

    chunk = pool_list[a.start:a.start + a.count]
    print("shard %s rows %d..%d (n=%d of pool %d)" % (
        a.shard, a.start, a.start + len(chunk) - 1, len(chunk), len(pool_list)), flush=True)
    if not chunk:
        print("  EMPTY CHUNK -- start %d is past the end of the pool (len %d). Nothing to build." % (
            a.start, len(pool_list)), flush=True)
    # Per-shard ids, written next to the volumes.  These are the ONLY self-contained evidence that
    # row k of vols_<shard>.npy is the study we think it is, so they are written before any pixel.
    np.save(os.path.join(WORK, "ids_%s.npy" % a.shard), np.array(chunk))
    n_slot = sum(g[2] for g in groups)
    V = np.zeros((len(chunk), n_slot, OUT, OUT), np.uint8)
    M = np.zeros((len(chunk), n_slot), np.uint8)
    done = 0
    with Pool(a.threads, initializer=_init, initargs=(ts, root, groups, span)) as p:
        for uid, v, m, _ in p.imap_unordered(build_study, chunk):
            i = chunk.index(uid)
            V[i], M[i] = v, m
            done += 1
            if done % 20 == 0 or done < 4:
                el = time.time() - t0
                print("  [%4d/%4d] %.1fs/study  elapsed %.0fs  eta %.0fs" % (
                    done, len(chunk), el / done, el, el / done * (len(chunk) - done)), flush=True)
            if done % 200 == 0:
                np.save(os.path.join(WORK, "vols_%s.npy" % a.shard), V[:len(chunk)])
                np.save(os.path.join(WORK, "masks_%s.npy" % a.shard), M)
                np.save(os.path.join(WORK, "ids_%s.npy" % a.shard), np.array(chunk))
                print("  checkpoint at %d" % done, flush=True)

    np.save(os.path.join(WORK, "vols_%s.npy" % a.shard), V)
    np.save(os.path.join(WORK, "masks_%s.npy" % a.shard), M)
    np.save(os.path.join(WORK, "ids_%s.npy" % a.shard), np.array(chunk))
    print("shard %s: %s | mask density %.4f | %.0f MB | %.0fs" % (
        a.shard, V.shape, M.mean(), V.nbytes / 1e6, time.time() - t0), flush=True)
    print("DONE in %.0fs" % (time.time() - t0), flush=True)


if __name__ == "__main__":
    main()
